  if(!Array.isArray(pending.items)||!Number.isSafeInteger(summary.published)||!Number.isSafeInteger(shadow.totalHumanDecisions)||!Array.isArray(history.items))throw Error('管理データの形式を確認できません');
  items=pending.items;if(inspectedId&&/^[-a-zA-Z0-9_]{1,128}$/.test(inspectedId))inspectedArticle=await api('/api/candidates/'+encodeURIComponent(inspectedId));dashboardView(summary);shadowView(shadow);historyView(history,true);
  const previous=$('source').value;$('source').replaceChildren(new Option('すべての情報源','all'));for(const [id,name]of new Map(items.map(x=>[x.sourceId,x.source])))$('source').add(new Option(name,id));if([...$('source').options].some(x=>x.value===previous))$('source').value=previous;renderList();
