 const inputs={},confirmations={};
 function field(key,label,kind='text'){const l=el('label',label),i=el('input');i.type=kind;i.required=true;if(kind==='text')i.maxLength=60;i.setAttribute('aria-label',label);l.append(i);inputs[key]=i;fields.append(l);return i;}
 function rebuild(){fields.replaceChildren();for(const k of Object.keys(inputs))delete inputs[k];const t=review.types[type.value];field('subject',t.product?'正式な製品・モデル名（原見出しは入力しない）':'確認できた対象名（人物・イベント・資料・サービス等）');if(t.product){const l=el('label','明示された製品種別'),i=el('select');i.setAttribute('aria-label','明示された製品種別');for(const name of review.productTypes)i.add(new Option(name,name));inputs.productType=i;l.append(i);fields.append(l);}if(t.event){field('eventDate','開催日','date');field('endDate','最終開催日（複数日の場合のみ）','date').required=false;field('venue','会場');}if(t.release)field('releaseDate','発売日','date');if(['recruitment','competition'].includes(type.value))field('deadline','募集・応募の締切（明示されている場合）','date').required=false;for(const c of Object.values(confirmations))c.checked=false;}
 for(const [key,label]of [['primaryArticleChecked','リンク先の原記事を自分で確認した'],['subjectActionBound','主体・対象・行為が同じ記事で明示されている'],['acousticRelevanceChecked','アコースティックギターとの関連を確認した'],['noOriginalTextCopied','原見出し・本文の転載や推測の補完をしていない']]){const l=el('label'),i=el('input');i.type='checkbox';confirmations[key]=i;l.append(i,document.createTextNode(label));checks.append(l);}
